// Every guide loads, its card/section counts match app/lib/studyMeta.json (regenerated by
// `npm run study:index`), the phone-menu markup is present, and no card contains obviously
// broken content (a stray template placeholder, an unresolved {{go}} link, etc).
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

export async function run({ browser, base, ok }) {
  const meta = JSON.parse(await readFile(path.join(ROOT, 'app', 'lib', 'studyMeta.json'), 'utf8'));
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  for (const slug of Object.keys(meta).filter((k) => k !== '_all')) {
    await page.goto(`${base}/${slug}`, { waitUntil: 'networkidle' });
    const frame = await (await page.waitForSelector('iframe')).contentFrame();
    await frame.waitForSelector('#navList .nav-item', { state: 'attached' });
    const r = await frame.evaluate(() => ({
      cards: INDEX.length,
      sections: DATA.length,
      toggle: !!document.getElementById('navToggle'),
      junk: INDEX.filter((e) => /\[object Object\]|\{\{|\bNaN\b/.test(e.item.a.replace(/<pre[\s\S]*?<\/pre>/g, '').replace(/<code>[\s\S]*?<\/code>/g, ''))).length,
      unresolvedGo: INDEX.filter((e) => [...e.item.a.matchAll(/data-go="([^":]+):(\d+)"/g)].some((m) => { const s = DATA.find((x) => x.id === m[1]); return !s || !s.questions[Number(m[2])]; })).length,
    }));
    ok(`${slug}: card/section counts match studyMeta`, r.cards === meta[slug].cards && r.sections === meta[slug].sections, `${r.cards} cards / ${r.sections} sections`);
    ok(`${slug}: phone menu + no junk text + links resolve`, r.toggle && r.junk === 0 && r.unresolvedGo === 0, JSON.stringify({ junk: r.junk, badLinks: r.unresolvedGo }));
  }
  await page.close();
}
